import{_ as s,o as a,c as n,a3 as i}from"./chunks/framework.DDp5PACv.js";const k=JSON.parse('{"title":"Code reference format","description":"","frontmatter":{},"headers":[],"relativePath":"formats/code-reference.md","filePath":"formats/code-reference.md"}'),t={name:"formats/code-reference.md"};function o(l,e,p,r,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="code-reference-format" tabindex="-1">Code reference format <a class="header-anchor" href="#code-reference-format" aria-label="Permalink to &quot;Code reference format&quot;">​</a></h1><p>Authoring contract for Code Reference pages. Pages live under <code>docs/sections/</code> and generate the VitePress site. The GitHub README inlines the intro pages and links here. Examples are copied from named tests into <code>docs/examples/</code>; keep this structure parseable.</p><p>Not published in the sidebar (<code>toc.yaml</code>).</p><p>Layout follows MSDN-style API pages: title, summary, language selector, member tables, then a definition and parameters for each Constructor and Methods member. Properties render as a table only.</p><h2 id="page-shape" tabindex="-1">Page shape <a class="header-anchor" href="#page-shape" aria-label="Permalink to &quot;Page shape&quot;">​</a></h2><p>Required sections, in order:</p><ol><li><code># {MajorClass}</code> — one major type per page</li><li>Summary paragraph(s) — dialect-neutral</li><li>Dialect selector — injected before <code>## Classes</code>; switches class lists and examples</li><li><code>## Classes</code> plus one <code>::: reference</code> block</li><li><code>## Remarks</code> — extra usage advice (always present; can be short)</li><li><code>## Examples</code> — omit the heading when there are zero samples</li></ol><p>Associated types belong on the same page (Transaction covers Transaction and IsolationLevel). Extra types are extra <code>####</code> headings in each dialect panel.</p><p>Sidebar nesting: a child sets <code>parent</code> to an existing page title. That page is the clickable group. There are no label-only groups.</p><p>After the major class and its instance type, document any <strong>page-local</strong> type that appears in a parameter or return and does not have its own Code Reference page (for example <code>DatasourceOptions</code> on Datasource). Language primitives (<code>string</code>, <code>void</code>, <code>HashMap</code>) are not listed as classes. Types with their own page (<code>IConnection</code>, <code>ICommand</code>, repositories, <code>IDatasourceFactory</code>) stay links. Parameter and return text links to the type. If another page uses the same type, document it once and link from the other page. C# and Rust may still use the conceptual heading when the runtime type is a dictionary.</p><h2 id="class-list-reference" tabindex="-1">Class list (<code>::: reference</code>) <a class="header-anchor" href="#class-list-reference" aria-label="Permalink to &quot;Class list (`::: reference`)&quot;">​</a></h2><p>Reserved panel markers (stripped by the transform): <code>### typescript</code>, <code>### csharp</code>, <code>### rust</code>. Aliases: <code>ts</code>, <code>cs</code>, <code>rs</code>.</p><p>Each class has an optional definition fence, then <code>**Constructor**</code> / <code>**Properties**</code> / <code>**Methods**</code> groups. Each member is a <code>#####</code> heading: short description, definition fence, parameter list, optional <code>**Returns**</code>. The transform builds the Name / Description tables from those members. Properties stay as that table; Constructor and Methods also get a definition and parameters.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Classes</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: reference</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### typescript</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### Datasource</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```typescript</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">class Datasource</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Methods**</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">##### create(options?)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Creates a datasource from the registry.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```typescript</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">static create(options?: DatasourceOptions): IDatasource</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `options`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">DatasourceOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">#datasourceoptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); omitted loads </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`.env`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, then process </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`INSTALLED_PROVIDERS`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`PROVIDER`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, and </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`DATASOURCE_URL`</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Returns**</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `IDatasource`</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div><p>Rules:</p><ul><li>Document each member once. Do not hand-write the top member tables.</li><li>Use <code>**Constructor**</code>, <code>**Properties**</code>, and <code>**Methods**</code> as the only group labels. Omit a group when the type has none.</li><li>The first paragraph under a member is the table description. Constructor and Methods also use it as the detail lead.</li><li>Parameter lines are <code>- \\</code>name` — description<code>. Link page-local and cross-page types (</code><a href="#datasourceoptions">DatasourceOptions</a><code>, </code><a href="./../sections/datasource-factory.html">IDatasourceFactory</a>`).</li><li>Rust may use a module heading (<code>#### datasources</code>) for free functions when there is no registry class.</li></ul><p>VitePress uses one page-level dialect selector for classes and examples. README expands each panel under <code>#### TypeScript</code> / <code>#### C#</code> / <code>#### Rust</code>.</p><h2 id="dialect-names" tabindex="-1">Dialect names <a class="header-anchor" href="#dialect-names" aria-label="Permalink to &quot;Dialect names&quot;">​</a></h2><p>A summary or remark names an API once per sentence. The marker has three slots, in order C#, TypeScript, Rust. Repeat a slot when two dialects share a spelling. Write a <code>|</code> inside a slot as <code>\\|</code>. The site shows the slot for the selected language. README keeps all three in the sentence.</p><p>A <code>::: prose</code> block is for a sentence that is not the same fact under another name. Use <code>### typescript</code>, <code>### csharp</code>, and <code>### rust</code>. Omit a heading when that dialect has nothing to say. Shared sentences stay outside the block. README quotes that sentence under the dialect name so the following remarks stay shared.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The connection must be open before {{Execute|execute|execute}} or {{ExecuteReader|executeReader|execute_reader}}.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: prose</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### rust</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`Command`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> trait has no connection getter.</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>When present, one <code>###</code> heading per sample, optional prose, then <code>::: example</code>. Each fence points at a test or type by name (<code>path#Name</code>), not a line range. <code>npm run docs:examples</code> writes the usage sample — not the test method wrapper or equality asserts — into <code>docs/examples/&lt;heading&gt;/&lt;File&gt;.&lt;Name&gt;.&lt;lang&gt;</code>. The test path and line range live in <code>docs/examples/lines</code>. The same command rewrites <code>docs/examples.md</code> as an index of those samples. The transform renders the sample file. Do not paste a second fictional fence. A source icon opens the recorded line range from the repo. README links that range on GitHub. On a reference page those fences follow the page-level selector; they do not get their own tabs.</p><p>A new fence may use <code>path#Lstart-Lend</code> once. The command rewrites it to the region name and stores that slice. After that, <code>path#Name</code> is the pointer. Run <code>npm run docs:examples</code> after adding a sample. A Cursor hook runs it when a cited <code>.cs</code>, <code>.rs</code>, or <code>.ts</code> file changes.</p><p>Optional <code>output</code> fences after the sample fences become titled textboxes under the sample. Use a shared fence for every dialect, or <code>output:typescript</code> / <code>output:csharp</code> / <code>output:rust</code> to replace a same-title box for one language.</p><p>A test loads a catalog schema with <code>SchemaSpec.Apply</code>, <code>applySchema</code>, or <code>apply_schema</code> after <code>Open</code> / <code>open</code> and before the usage that becomes the sample. Those two calls are left out of the sample. The schema name is stored on the example line record. The page shows that schema, as <code>CREATE TABLE</code> text, outside the code sample and links it to the matching heading under Schemas on the Examples page. Seed SQL stays in the sample. All three languages for one sample name the same schema.</p><p><code>::: dialects</code> stays for install or CLI snippets that are not tests.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Examples</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Create from environment</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: example</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```csharp csharp/Datasources.Tests/DatasourceFactoryTests.cs#DefaultFromEnvironment</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```rust rust/datasources/src/tests/datasource_factory.rs#default_from_environment</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```typescript typescript/datasources/src/DatasourceFactory.test.ts#default-from-environment</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: example</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```csharp csharp/Datasources.Tests/TransformMapperTests.cs#FlattensAndUnflattensUserAndContacts</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```rust rust/datasources/src/mappers/mod.rs#flattens_and_unflattens_user_and_contacts</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```typescript typescript/datasources/src/mappers/transformMapper.test.ts#flattens-and-unflattens-user-and-contacts</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```output [Before: nested value]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  user: { id: 1, name: &#39;Ada&#39; },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  contacts: { email: &#39;ada@x.dev&#39;, phone: &#39;555&#39; }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```output [After: flat value]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  userId: 1,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  userName: &#39;Ada&#39;,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  contactEmail: &#39;ada@x.dev&#39;,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  contactPhone: &#39;555&#39;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul><li>[ ] Title is the major class name</li><li>[ ] Summary keeps one sentence; dialect API names use the three-slot marker</li><li>[ ] <code>## Classes</code> wraps one <code>::: reference</code> with all three panels</li><li>[ ] Each member has a description; Constructor and Methods also have a definition and parameters (Properties render as a table only)</li><li>[ ] Associated types and page-local argument/return types are extra <code>####</code> headings, not a second page</li><li>[ ] <code>## Remarks</code> is present</li><li>[ ] Examples use <code>::: example</code> name pointers (<code>path#Name</code>) or the Examples heading is omitted</li><li>[ ] Nested sidebar items set <code>parent</code> in <code>docs/toc.yaml</code> to the group label</li><li>[ ] Page is listed in <code>docs/toc.yaml</code></li></ul>',31)])])}const E=s(t,[["render",o]]);export{k as __pageData,E as default};
